CREATE TABLE `assignment_questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `subject_id` int NOT NULL,
  `unit_id` int NOT NULL,
  `assignment_number` int NOT NULL,
  `question_text` text NOT NULL,
  `assignment_type` varchar(30) NOT NULL DEFAULT 'descriptive',
  `co_mapping` varchar(50) DEFAULT NULL,
  `bloom_level` varchar(20) DEFAULT 'Apply',
  `marks` int NOT NULL DEFAULT '10',
  `is_active` tinyint(1) DEFAULT '1',
  `is_pending` tinyint(1) DEFAULT '0',
  `usage_count` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `subject_id` (`subject_id`),
  KEY `unit_id` (`unit_id`),
  CONSTRAINT `assignment_questions_ibfk_1` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`),
  CONSTRAINT `assignment_questions_ibfk_2` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=415 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
