DROP TABLE IF EXISTS `question_groups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question_groups` (
  `id` int NOT NULL AUTO_INCREMENT,
  `subject_id` int NOT NULL,
  `unit_id` int NOT NULL,
  `topic_id` int DEFAULT NULL,
  `total_marks` int NOT NULL,
  `difficulty` varchar(20) DEFAULT NULL,
  `question_type` varchar(20) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `usage_count` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `is_pending` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `subject_id` (`subject_id`),
  KEY `unit_id` (`unit_id`),
  CONSTRAINT `question_groups_ibfk_1` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`),
  CONSTRAINT `question_groups_ibfk_2` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4771 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

